<?php require_once '../config.php'; login_required('admin'); $msg=''; if(isset($_GET['delete'])){ $id=(int)$_GET['delete']; mysqli_query($conn,"DELETE FROM books WHERE id=$id");$msg='Book deleted.';} $rows=mysqli_query($conn,'SELECT * FROM books ORDER BY id DESC'); ?><!doctype html><html><head><title>Books</title><link rel="stylesheet" href="../assets/css/admin/books.css"><link rel="stylesheet" href="../assets/css/admin/sidebar.css"></head><body><div class="layout"><?php include 'sidebar.php';?><main class="main"><div class="top"><h1>Books</h1><a class="btn" href="add_book.php">Add Book</a></div><?php if($msg):?><div class="success"><?=$msg?></div><?php endif;?><div class="panel"><table><tr><th>ID</th><th>Title</th><th>Author</th><th>Category</th><th>Qty</th><th>Available</th><th>Action</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=$r['id']?></td><td><?=e($r['title'])?></td><td><?=e($r['author'])?></td><td><?=e($r['category'])?></td><td><?=$r['quantity']?></td><td><?=$r['available']?></td><td><a class="btn small danger" onclick="return confirm('Delete?')" href="?delete=<?=$r['id']?>">Delete</a></td></tr><?php endwhile;?></table></div></main></div></body></html>
